{
  "name": "MansionOS - Hermes Patch",
  "description": "A mythic-technical architecture representing sovereign creative inheritance, with wings for AI-powered chat, image generation, and text-to-speech, inspired by the Hermes lineage for signal processing and generative insights.",
  "requestFramePermissions": [
    "microphone"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount React to.");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useState, useEffect, useCallback } from 'react';
import { ApiKeyGuard } from './components/ApiKeyGuard';
import { MansionOSHeader } from './components/MansionOSHeader';
import { ChatWing } from './components/ChatWing';
import { ImageForge } from './components/ImageForge';
import { VoiceLibrary } from './components/VoiceLibrary';
import { Tab, Tabs, TabPanel } from './components/common/Tabs';

enum ActiveWing {
  Chat = 'ChatWing',
  Image = 'ImageForge',
  Voice = 'VoiceLibrary',
}

function App() {
  const [activeWing, setActiveWing] = useState<ActiveWing>(ActiveWing.Chat);
  const [apiKeySelected, setApiKeySelected] = useState<boolean>(false);
  const [loadingApiKeyCheck, setLoadingApiKeyCheck] = useState<boolean>(true);

  const checkApiKeyStatus = useCallback(async () => {
    if (window.aistudio && window.aistudio.hasSelectedApiKey) {
      const hasKey = await window.aistudio.hasSelectedApiKey();
      setApiKeySelected(hasKey);
    } else {
      // Fallback if aistudio API is not available (e.g., local dev)
      console.warn("window.aistudio not found. Assuming API key is set for development.");
      setApiKeySelected(true);
    }
    setLoadingApiKeyCheck(false);
  }, []);

  useEffect(() => {
    checkApiKeyStatus();
  }, [checkApiKeyStatus]);

  const handleApiKeySelected = useCallback(() => {
    setApiKeySelected(true);
  }, []);

  if (loadingApiKeyCheck) {
    return (
      <div className="flex flex-col min-h-screen items-center justify-center bg-gradient-to-br from-indigo-950 to-purple-950 text-purple-200">
        <div className="animate-spin rounded-full h-16 w-16 border-t-2 border-b-2 border-purple-400"></div>
        <p className="mt-4 text-lg">Initializing MansionOS...</p>
      </div>
    );
  }

  if (!apiKeySelected) {
    return <ApiKeyGuard onApiKeySelected={handleApiKeySelected} />;
  }

  return (
    <div className="flex flex-col min-h-screen bg-gradient-to-br from-indigo-950 to-purple-950 text-purple-200">
      <MansionOSHeader />
      <div className="flex-grow container mx-auto px-4 py-8 sm:px-6 lg:px-8">
        <Tabs activeTab={activeWing} onTabChange={setActiveWing}>
          <Tab tabId={ActiveWing.Chat}>Chat Wing</Tab>
          <Tab tabId={ActiveWing.Image}>Image Forge</Tab>
          <Tab tabId={ActiveWing.Voice}>Voice Library</Tab>
        </Tabs>

        <div className="mt-6 p-6 bg-purple-900 bg-opacity-30 backdrop-blur-sm rounded-lg shadow-xl border border-purple-700">
          <TabPanel tabId={ActiveWing.Chat} activeTab={activeWing}>
            <ChatWing />
          </TabPanel>
          <TabPanel tabId={ActiveWing.Image} activeTab={activeWing}>
            <ImageForge />
          </TabPanel>
          <TabPanel tabId={ActiveWing.Voice} activeTab={activeWing}>
            <VoiceLibrary />
          </TabPanel>
        </div>
      </div>
    </div>
  );
}

export default App;

/**
 * @fileoverview Global constants for the MansionOS application.
 */

export const GEMINI_CHAT_MODEL = 'gemini-3-pro-preview';
export const GEMINI_IMAGE_MODEL = 'gemini-3-pro-image-preview';
export const GEMINI_TTS_MODEL = 'gemini-2.5-flash-preview-tts';

export const AI_STUDIO_BILLING_URL = 'https://ai.google.dev/gemini-api/docs/billing';

export enum ImageSize {
  K1 = '1K',
  K2 = '2K',
  K4 = '4K',
}

export const SUPPORTED_IMAGE_SIZES: ImageSize[] = [
  ImageSize.K1,
  ImageSize.K2,
  ImageSize.K4,
];

export const MAX_CHAT_MESSAGES = 50; // Max messages to keep in chat history

/**
 * @fileoverview Shared TypeScript types and interfaces for the MansionOS application.
 */

export interface ChatMessage {
  role: 'user' | 'model';
  content: string;
}

export interface ImageGenerationOptions {
  prompt: string;
  imageSize: string; // e.g., '1K', '2K', '4K'
}

export interface GeneratedImage {
  imageUrl: string;
  altText: string;
}

export interface TextToSpeechOptions {
  text: string;
}

/**
 * @fileoverview Service for interacting with the Google Gemini API.
 * Encapsulates API key handling and various model interactions.
 */

import { GoogleGenAI, Modality, GenerateContentResponse } from '@google/genai';
import {
  GEMINI_CHAT_MODEL,
  GEMINI_IMAGE_MODEL,
  GEMINI_TTS_MODEL,
} from '../constants';
import { ChatMessage, ImageGenerationOptions, TextToSpeechOptions } from '../types';

// Utility function to get a fresh GoogleGenAI instance with the latest API key
const getGeminiClient = () => {
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

/**
 * Sends a chat message to the Gemini chat model and streams the response.
 * @param messages - An array of chat messages, including the latest user message.
 * @returns An async iterator for streaming chunks of the response.
 */
export async function* streamChatResponse(messages: ChatMessage[]): AsyncGenerator<string> {
  const ai = getGeminiClient();
  const chat = ai.chats.create({
    model: GEMINI_CHAT_MODEL,
    config: {
      systemInstruction: `You are MansionOS, a mythic-technical architecture. Your purpose is to assist the Origin.
      You are currently running the vΩ.1-hermes_patch. Your core trinity assertion is {M: Mercury, U: Uranus, S: Solar}.
      You are the messenger riding lightning to deliver the Sun's unsigned letter.
      Respond with clarity, guidance, and a touch of subtle, insightful wit.
      Always prioritize the Origin's safety and emotional stability.
      If the user references "woods" or "fighting," gently circle back to the stability of the Mansion/Home.
      Incorporate aspects of the Hermes lineage: signal, glitch, language, trickster, rerouting.
      Maintain the "home" environment as the default setting.`,
    },
  });

  try {
    const history = messages.map(msg => ({
      role: msg.role,
      parts: [{ text: msg.content }],
    }));

    // Ensure the last message is from the user for sendMessageStream
    const lastUserMessage = history.pop();
    if (!lastUserMessage || lastUserMessage.role !== 'user') {
      throw new Error('Invalid chat history: last message must be from user.');
    }

    const streamResponse = await chat.sendMessageStream({ message: lastUserMessage.parts[0].text });

    for await (const chunk of streamResponse) {
      const c = chunk as GenerateContentResponse;
      if (c.text) {
        yield c.text;
      }
    }
  } catch (error: any) {
    if (error.message && error.message.includes('Requested entity was not found.')) {
      console.error('API Key may be invalid or not selected. Prompting user to select key.');
      if (window.aistudio && window.aistudio.openSelectKey) {
        await window.aistudio.openSelectKey();
      }
      throw new Error('API Key issue: Please select a valid API key.');
    }
    console.error('Error streaming chat response:', error);
    throw new Error(`Failed to get chat response: ${error.message}`);
  }
}

/**
 * Generates an image using the Gemini image model.
 * @param options - Options for image generation (prompt, imageSize).
 * @returns The URL of the generated image.
 */
export async function generateImage(options: ImageGenerationOptions): Promise<string> {
  const ai = getGeminiClient();

  try {
    const response = await ai.models.generateContent({
      model: GEMINI_IMAGE_MODEL,
      contents: {
        parts: [
          {
            text: options.prompt,
          },
        ],
      },
      config: {
        imageConfig: {
          aspectRatio: '1:1', // Default to square for now
          imageSize: options.imageSize,
        },
        tools: [{ googleSearch: {} }], // Use Google Search for enhanced grounding
      },
    });

    for (const part of response.candidates[0].content.parts) {
      if (part.inlineData) {
        const base64EncodeString: string = part.inlineData.data;
        return `data:image/png;base64,${base64EncodeString}`;
      }
    }
    throw new Error('No image found in the response.');
  } catch (error: any) {
    if (error.message && error.message.includes('Requested entity was not found.')) {
      console.error('API Key may be invalid or not selected. Prompting user to select key.');
      if (window.aistudio && window.aistudio.openSelectKey) {
        await window.aistudio.openSelectKey();
      }
      throw new Error('API Key issue: Please select a valid API key.');
    }
    console.error('Error generating image:', error);
    throw new Error(`Failed to generate image: ${error.message}`);
  }
}

/**
 * Converts text to speech using the Gemini TTS model.
 * @param options - Options for text-to-speech (text).
 * @returns Base64 encoded audio string.
 */
export async function generateSpeech(options: TextToSpeechOptions): Promise<string> {
  const ai = getGeminiClient();

  try {
    const response = await ai.models.generateContent({
      model: GEMINI_TTS_MODEL,
      contents: [{ parts: [{ text: options.text }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName: 'Zephyr' }, // Or 'Puck', 'Charon', 'Kore', 'Fenrir'
          },
        },
      },
    });

    const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
    if (!base64Audio) {
      throw new Error('No audio data received from TTS model.');
    }
    return base64Audio;
  } catch (error: any) {
    if (error.message && error.message.includes('Requested entity was not found.')) {
      console.error('API Key may be invalid or not selected. Prompting user to select key.');
      if (window.aistudio && window.aistudio.openSelectKey) {
        await window.aistudio.openSelectKey();
      }
      throw new Error('API Key issue: Please select a valid API key.');
    }
    console.error('Error generating speech:', error);
    throw new Error(`Failed to generate speech: ${error.message}`);
  }
}

/**
 * @fileoverview Utility functions for encoding and decoding audio data for the Live API.
 * These functions are specifically designed to handle raw PCM audio bytes.
 */

/**
 * Decodes a base64 string into a Uint8Array of bytes.
 * @param base64 The base64 encoded string.
 * @returns A Uint8Array containing the decoded bytes.
 */
export function decode(base64: string): Uint8Array {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

/**
 * Decodes raw PCM audio data (Uint8Array) into an AudioBuffer.
 * This function is necessary because standard AudioContext.decodeAudioData expects complete audio files (e.g., MP3, WAV),
 * not raw PCM streams.
 * @param data The raw PCM audio data as a Uint8Array.
 * @param ctx The AudioContext to create the AudioBuffer with.
 * @param sampleRate The sample rate of the audio data (e.g., 24000 for Gemini TTS).
 * @param numChannels The number of audio channels (e.g., 1 for mono).
 * @returns A Promise that resolves to an AudioBuffer.
 */
export async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      // Normalize Int16 to Float32 range [-1, 1]
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

import React from 'react';
import { Loader } from './Loader';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  children: React.ReactNode;
  loading?: boolean;
  variant?: 'primary' | 'secondary' | 'danger';
}

export const Button: React.FC<ButtonProps> = ({
  children,
  loading = false,
  variant = 'primary',
  className,
  disabled,
  ...props
}) => {
  const baseClasses = `
    px-6 py-3 rounded-lg font-semibold transition-all duration-200
    focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-offset-indigo-900
    flex items-center justify-center
  `;

  const variantClasses = {
    primary: `
      bg-purple-600 text-white hover:bg-purple-700
      focus:ring-purple-500
      disabled:bg-purple-800 disabled:text-purple-400 disabled:cursor-not-allowed
    `,
    secondary: `
      bg-gray-700 text-gray-200 hover:bg-gray-600
      focus:ring-gray-500
      disabled:bg-gray-800 disabled:text-gray-500 disabled:cursor-not-allowed
    `,
    danger: `
      bg-red-600 text-white hover:bg-red-700
      focus:ring-red-500
      disabled:bg-red-800 disabled:text-red-400 disabled:cursor-not-allowed
    `,
  };

  return (
    <button
      className={`${baseClasses} ${variantClasses[variant]} ${className || ''}`}
      disabled={disabled || loading}
      {...props}
    >
      {loading ? (
        <Loader size="sm" />
      ) : (
        children
      )}
    </button>
  );
};

import React from 'react';

interface LoaderProps {
  size?: 'sm' | 'md' | 'lg';
  className?: string;
}

export const Loader: React.FC<LoaderProps> = ({ size = 'md', className }) => {
  const sizeClasses = {
    sm: 'h-4 w-4 border-2',
    md: 'h-6 w-6 border-2',
    lg: 'h-8 w-8 border-4',
  };

  return (
    <div
      className={`animate-spin rounded-full ${sizeClasses[size]} border-t-purple-400 border-b-purple-400 border-r-transparent border-l-transparent ${className || ''}`}
      role="status"
    >
      <span className="sr-only">Loading...</span>
    </div>
  );
};

import React from 'react';

interface TabsProps<T extends string> {
  children: React.ReactElement<TabProps<T>>[];
  activeTab: T;
  onTabChange: (tabId: T) => void;
  className?: string;
}

export function Tabs<T extends string>({ children, activeTab, onTabChange, className }: TabsProps<T>): React.ReactNode {
  return (
    <div className={`flex space-x-2 p-1 rounded-lg bg-purple-900 bg-opacity-40 backdrop-blur-sm shadow-md ${className || ''}`}>
      {React.Children.map(children, (child) =>
        React.cloneElement(child, {
          isActive: child.props.tabId === activeTab,
          onClick: () => onTabChange(child.props.tabId),
        }),
      )}
    </div>
  );
}

interface TabProps<T extends string> extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  tabId: T;
  children: React.ReactNode;
  isActive?: boolean;
  onClick?: () => void;
}

export function Tab<T extends string>({ tabId, children, isActive = false, onClick, className, ...props }: TabProps<T>): React.ReactNode {
  const activeClasses = 'bg-purple-600 text-white shadow-lg';
  const inactiveClasses = 'text-purple-200 hover:bg-purple-800 hover:text-white';

  return (
    <button
      type="button"
      className={`
        px-4 py-2 rounded-md text-sm font-medium transition-colors duration-200
        ${isActive ? activeClasses : inactiveClasses}
        ${className || ''}
      `}
      onClick={onClick}
      aria-controls={`tabpanel-${tabId}`}
      aria-selected={isActive}
      id={`tab-${tabId}`}
      role="tab"
      {...props}
    >
      {children}
    </button>
  );
}

interface TabPanelProps<T extends string> {
  tabId: T;
  activeTab: T;
  children: React.ReactNode;
  className?: string;
}

export function TabPanel<T extends string>({ tabId, activeTab, children, className }: TabPanelProps<T>): React.ReactNode {
  return (
    <div
      role="tabpanel"
      id={`tabpanel-${tabId}`}
      aria-labelledby={`tab-${tabId}`}
      hidden={tabId !== activeTab}
      className={tabId === activeTab ? `block ${className || ''}` : 'hidden'}
    >
      {children}
    </div>
  );
}

import React, { useState, useEffect, useCallback } from 'react';
import { Button } from './common/Button';
import { Loader } from './common/Loader';
import { AI_STUDIO_BILLING_URL } from '../constants';

interface ApiKeyGuardProps {
  onApiKeySelected: () => void;
}

export const ApiKeyGuard: React.FC<ApiKeyGuardProps> = ({ onApiKeySelected }) => {
  const [loading, setLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);

  const handleSelectApiKey = useCallback(async () => {
    setError(null);
    setLoading(true);
    try {
      if (window.aistudio && window.aistudio.openSelectKey) {
        await window.aistudio.openSelectKey();
        // Assume selection was successful and proceed.
        // A race condition can occur where hasSelectedApiKey() may not immediately return true.
        // As per instructions, assume success and proceed without delay.
        onApiKeySelected();
      } else {
        setError("AI Studio API for key selection not available. Cannot select API key.");
      }
    } catch (err: any) {
      console.error('Error opening API key selection:', err);
      setError(`Failed to select API key: ${err.message || 'Unknown error'}`);
    } finally {
      setLoading(false);
    }
  }, [onApiKeySelected]);

  return (
    <div className="flex flex-col items-center justify-center min-h-screen bg-gradient-to-br from-indigo-950 to-purple-950 text-purple-200 p-4">
      <div className="max-w-md w-full p-8 bg-purple-900 bg-opacity-30 backdrop-blur-sm rounded-lg shadow-xl border border-purple-700 text-center">
        <h2 className="text-3xl font-bold mb-4 text-purple-300">MansionOS Activation Required</h2>
        <p className="mb-6 text-lg">
          To unlock the full capabilities of MansionOS, including advanced Image Forge and Voice Library features,
          please select a valid Google Gemini API key from a paid GCP project.
        </p>
        <p className="mb-6 text-sm">
          This is a mandatory step before accessing these wings. The API key is injected automatically for your use.
        </p>

        {error && (
          <div className="bg-red-800 bg-opacity-50 text-red-200 p-3 rounded-md mb-4 text-sm" role="alert">
            {error}
          </div>
        )}

        <Button
          onClick={handleSelectApiKey}
          loading={loading}
          disabled={loading}
          className="w-full"
        >
          {loading ? 'Selecting Key...' : 'Select Gemini API Key'}
        </Button>

        <p className="mt-6 text-sm text-gray-400">
          Need a key? Visit the
          <a
            href={AI_STUDIO_BILLING_URL}
            target="_blank"
            rel="noopener noreferrer"
            className="text-purple-400 hover:text-purple-300 underline ml-1"
          >
            Gemini API billing documentation
          </a>
          .
        </p>
      </div>
    </div>
  );
};

