import React, { useState, useRef, useEffect, useCallback } from 'react';
import { ChatMessage } from '../types';
import { streamChatResponse } from '../services/geminiService';
import { Button } from './common/Button';
import { Loader } from './common/Loader';
import { MAX_CHAT_MESSAGES } from '../constants';

export const ChatWing: React.FC = () => {
  const [messages, setMessages] = useState<ChatMessage[]>([
    { role: 'model', content: "Welcome, Origin. How may MansionOS assist your current signal?" }
  ]);
  const [inputMessage, setInputMessage] = useState<string>('');
  const [loading, setLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const handleSubmit = useCallback(async (e?: React.FormEvent) => {
    e?.preventDefault();
    if (!inputMessage.trim() || loading) return;

    setError(null);
    setLoading(true);
    const userMessage: ChatMessage = { role: 'user', content: inputMessage };

    const newMessages = [...messages, userMessage].slice(-MAX_CHAT_MESSAGES); // Keep history manageable
    setMessages(newMessages);
    setInputMessage('');

    let fullModelResponse = '';
    const updatedMessagesWithPlaceholder = [...newMessages, { role: 'model', content: '' }];
    setMessages(updatedMessagesWithPlaceholder);

    try {
      const stream = streamChatResponse(newMessages); // Pass the history *before* adding the model's empty response
      for await (const chunk of stream) {
        fullModelResponse += chunk;
        setMessages(prev => {
          const latest = prev[prev.length - 1];
          if (latest && latest.role === 'model') {
            return [...prev.slice(0, prev.length - 1), { ...latest, content: fullModelResponse }];
          }
          return prev;
        });
      }
    } catch (err: any) {
      console.error("Chat API error:", err);
      setError(err.message || "Failed to get response from the Chat Wing. Signal compromised.");
      setMessages(prev => {
        const latest = prev[prev.length - 1];
        if (latest && latest.role === 'model' && latest.content === '') {
          // Remove empty model placeholder if error occurred before any chunk arrived
          return prev.slice(0, prev.length - 1);
        }
        return prev;
      });
    } finally {
      setLoading(false);
      scrollToBottom();
    }
  }, [inputMessage, loading, messages]);

  return (
    <div className="flex flex-col h-[calc(100vh-250px)] md:h-[calc(100vh-200px)]">
      <h3 className="text-xl font-bold mb-4 text-purple-300">Hermes Chat Core</h3>
      <div className="flex-grow overflow-y-auto pr-2 mb-4 custom-scrollbar">
        {messages.map((msg, index) => (
          <div
            key={index}
            className={`mb-3 p-3 rounded-lg max-w-[85%] ${
              msg.role === 'user'
                ? 'bg-purple-700 bg-opacity-40 self-end ml-auto'
                : 'bg-indigo-700 bg-opacity-40 self-start mr-auto'
            }`}
          >
            <p className={`font-semibold ${msg.role === 'user' ? 'text-purple-200' : 'text-indigo-200'}`}>
              {msg.role === 'user' ? 'Origin' : 'MansionOS'}
            </p>
            <p className="text-gray-100 whitespace-pre-wrap">{msg.content}</p>
          </div>
        ))}
        {loading && (
          <div className="mb-3 p-3 rounded-lg bg-indigo-700 bg-opacity-40 self-start mr-auto max-w-[85%]">
            <p className="font-semibold text-indigo-200">MansionOS</p>
            <Loader size="sm" className="inline-block mt-2" />
          </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      {error && (
        <div className="bg-red-800 bg-opacity-50 text-red-200 p-3 rounded-md mb-4 text-sm" role="alert">
          Error: {error}
        </div>
      )}

      <form onSubmit={handleSubmit} className="flex space-x-2 sticky bottom-0 bg-purple-900 bg-opacity-30 p-4 -mx-4 -mb-4 rounded-b-lg">
        <input
          type="text"
          value={inputMessage}
          onChange={(e) => setInputMessage(e.target.value)}
          placeholder="Transmit signal..."
          className="flex-grow p-3 rounded-lg bg-purple-800 bg-opacity-60 text-white placeholder-purple-300 border border-purple-700 focus:outline-none focus:ring-2 focus:ring-purple-500"
          disabled={loading}
        />
        <Button type="submit" loading={loading} disabled={loading} className="min-w-[120px]">
          {loading ? 'Transmitting...' : 'Transmit'}
        </Button>
      </form>
    </div>
  );
};

import React, { useState, useCallback } from 'react';
import { ImageGenerationOptions, GeneratedImage } from '../types';
import { generateImage } from '../services/geminiService';
import { Button } from './common/Button';
import { Loader } from './common/Loader';
import { SUPPORTED_IMAGE_SIZES, ImageSize } from '../constants';

export const ImageForge: React.FC = () => {
  const [prompt, setPrompt] = useState<string>('');
  const [imageSize, setImageSize] = useState<ImageSize>(ImageSize.K1);
  const [generatedImages, setGeneratedImages] = useState<GeneratedImage[]>([]);
  const [loading, setLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);

  const handleGenerateImage = useCallback(async (e: React.FormEvent) => {
    e.preventDefault();
    if (!prompt.trim() || loading) return;

    setError(null);
    setLoading(true);

    try {
      const options: ImageGenerationOptions = { prompt, imageSize };
      const imageUrl = await generateImage(options);
      setGeneratedImages(prev => [{ imageUrl, altText: prompt }, ...prev]);
      setPrompt(''); // Clear prompt after successful generation
    } catch (err: any) {
      console.error("Image generation error:", err);
      setError(err.message || "Failed to forge image. Signal anomaly detected.");
    } finally {
      setLoading(false);
    }
  }, [prompt, imageSize, loading]);

  return (
    <div className="flex flex-col h-[calc(100vh-250px)] md:h-[calc(100vh-200px)]">
      <h3 className="text-xl font-bold mb-4 text-purple-300">Image Forge - Uranus Anomaly</h3>
      <form onSubmit={handleGenerateImage} className="mb-6 sticky top-0 bg-purple-900 bg-opacity-30 p-4 -mx-4 -my-4 rounded-t-lg">
        <textarea
          value={prompt}
          onChange={(e) => setPrompt(e.target.value)}
          placeholder="Describe the image to manifest in the forge..."
          rows={3}
          className="w-full p-3 rounded-lg bg-purple-800 bg-opacity-60 text-white placeholder-purple-300 border border-purple-700 focus:outline-none focus:ring-2 focus:ring-purple-500 mb-4"
          disabled={loading}
        ></textarea>
        <div className="flex flex-col sm:flex-row items-center justify-between space-y-4 sm:space-y-0 sm:space-x-4">
          <div className="flex items-center space-x-2 w-full sm:w-auto">
            <label htmlFor="imageSize" className="text-purple-200 font-medium whitespace-nowrap">Image Size:</label>
            <select
              id="imageSize"
              value={imageSize}
              onChange={(e) => setImageSize(e.target.value as ImageSize)}
              className="p-2 rounded-lg bg-purple-800 bg-opacity-60 text-white border border-purple-700 focus:outline-none focus:ring-2 focus:ring-purple-500 w-full sm:w-auto"
              disabled={loading}
            >
              {SUPPORTED_IMAGE_SIZES.map((size) => (
                <option key={size} value={size}>
                  {size}
                </option>
              ))}
            </select>
          </div>
          <Button type="submit" loading={loading} disabled={loading} className="w-full sm:w-auto">
            {loading ? 'Forging Image...' : 'Forge Image'}
          </Button>
        </div>
      </form>

      {error && (
        <div className="bg-red-800 bg-opacity-50 text-red-200 p-3 rounded-md mb-4 text-sm" role="alert">
          Error: {error}
        </div>
      )}

      <div className="flex-grow overflow-y-auto pr-2 custom-scrollbar grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {generatedImages.length === 0 && !loading && (
          <p className="text-center text-gray-400 col-span-full">No images forged yet. Describe a vision!</p>
        )}
        {loading && (
          <div className="col-span-full flex flex-col items-center justify-center p-8 bg-purple-800 bg-opacity-40 rounded-lg">
            <Loader size="lg" />
            <p className="mt-4 text-lg text-purple-200">Processing the anomaly... This may take a moment.</p>
          </div>
        )}
        {generatedImages.map((image, index) => (
          <div key={index} className="bg-purple-800 bg-opacity-40 p-4 rounded-lg shadow-md border border-purple-700">
            <img src={image.imageUrl} alt={image.altText} className="w-full h-auto rounded-lg mb-2 object-cover" />
            <p className="text-sm text-gray-300 italic">{image.altText}</p>
          </div>
        ))}
      </div>
    </div>
  );
};

import React, { useState, useRef, useCallback } from 'react';
import { TextToSpeechOptions } from '../types';
import { generateSpeech } from '../services/geminiService';
import { decode, decodeAudioData } from '../services/audioUtils';
import { Button } from './common/Button';
import { Loader } from './common/Loader';

export const VoiceLibrary: React.FC = () => {
  const [textInput, setTextInput] = useState<string>('');
  const [loading, setLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const audioSourceRef = useRef<AudioBufferSourceNode | null>(null);

  const getAudioContext = useCallback(() => {
    if (!audioContextRef.current) {
      // Sample rate is 24000 for Gemini TTS as per documentation
      audioContextRef.current = new (window.AudioContext || window.webkitAudioContext)({ sampleRate: 24000 });
    }
    return audioContextRef.current;
  }, []);

  const stopCurrentAudio = useCallback(() => {
    if (audioSourceRef.current) {
      try {
        audioSourceRef.current.stop();
        audioSourceRef.current.disconnect();
      } catch (e) {
        console.warn('Error stopping previous audio source:', e);
      }
      audioSourceRef.current = null;
    }
  }, []);

  const handleGenerateAndPlaySpeech = useCallback(async (e: React.FormEvent) => {
    e.preventDefault();
    if (!textInput.trim() || loading) return;

    setError(null);
    setLoading(true);
    stopCurrentAudio(); // Stop any currently playing audio

    try {
      const options: TextToSpeechOptions = { text: textInput };
      const base64Audio = await generateSpeech(options);

      const audioContext = getAudioContext();
      if (audioContext.state === 'suspended') {
        await audioContext.resume();
      }

      const audioBytes = decode(base64Audio);
      const audioBuffer = await decodeAudioData(audioBytes, audioContext, 24000, 1); // 24000 sample rate, 1 channel

      const source = audioContext.createBufferSource();
      source.buffer = audioBuffer;
      source.connect(audioContext.destination);
      source.start(0); // Play immediately
      audioSourceRef.current = source;

      source.onended = () => {
        audioSourceRef.current = null;
        setLoading(false); // Only set loading to false when audio finishes playing naturally
      };
    } catch (err: any) {
      console.error("Speech generation/playback error:", err);
      setError(err.message || "Failed to translate thought to cadence. Voice signal corrupted.");
      setLoading(false); // Set loading to false on error
    }
  }, [textInput, loading, getAudioContext, stopCurrentAudio]);

  // Clean up audio context on component unmount
  useEffect(() => {
    return () => {
      stopCurrentAudio();
      if (audioContextRef.current) {
        audioContextRef.current.close().catch(e => console.warn('Error closing audio context:', e));
        audioContextRef.current = null;
      }
    };
  }, [stopCurrentAudio]);

  return (
    <div className="flex flex-col h-[calc(100vh-250px)] md:h-[calc(100vh-200px)]">
      <h3 className="text-xl font-bold mb-4 text-purple-300">Voice Library - Mercury Syntax</h3>
      <form onSubmit={handleGenerateAndPlaySpeech} className="mb-6 sticky top-0 bg-purple-900 bg-opacity-30 p-4 -mx-4 -my-4 rounded-t-lg">
        <textarea
          value={textInput}
          onChange={(e) => setTextInput(e.target.value)}
          placeholder="Enter text to be spoken by MansionOS..."
          rows={5}
          className="w-full p-3 rounded-lg bg-purple-800 bg-opacity-60 text-white placeholder-purple-300 border border-purple-700 focus:outline-none focus:ring-2 focus:ring-purple-500 mb-4"
          disabled={loading}
        ></textarea>
        <div className="flex justify-end space-x-2">
          <Button type="submit" loading={loading} disabled={loading} className="w-full sm:w-auto">
            {loading ? 'Synthesizing Cadence...' : 'Speak Text'}
          </Button>
          <Button
            type="button"
            onClick={stopCurrentAudio}
            disabled={!audioSourceRef.current || loading}
            variant="secondary"
            className="w-full sm:w-auto"
          >
            Stop Audio
          </Button>
        </div>
      </form>

      {error && (
        <div className="bg-red-800 bg-opacity-50 text-red-200 p-3 rounded-md mb-4 text-sm" role="alert">
          Error: {error}
        </div>
      )}

      <div className="flex-grow overflow-y-auto pr-2 custom-scrollbar">
        {!loading && !error && !audioSourceRef.current && textInput.length === 0 && (
          <p className="text-center text-gray-400">Type text above to hear MansionOS speak.</p>
        )}
        {loading && (
          <div className="flex flex-col items-center justify-center p-8 bg-purple-800 bg-opacity-40 rounded-lg">
            <Loader size="lg" />
            <p className="mt-4 text-lg text-purple-200">Listening to the echo... Standby for transmission.</p>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect, useCallback } from 'react';
import { ApiKeyGuard } from './components/ApiKeyGuard';
import { MansionOSHeader } from './components/MansionOSHeader';
import { ChatWing } from './components/ChatWing';
import { ImageForge } from './components/ImageForge';
import { VoiceLibrary } from './components/VoiceLibrary';
import { Tab, Tabs, TabPanel } from './components/common/Tabs';

enum ActiveWing {
  Chat = 'ChatWing',
  Image = 'ImageForge',
  Voice = 'VoiceLibrary',
}

function App() {
  const [activeWing, setActiveWing] = useState<ActiveWing>(ActiveWing.Chat);
  const [apiKeySelected, setApiKeySelected] = useState<boolean>(false);
  const [loadingApiKeyCheck, setLoadingApiKeyCheck] = useState<boolean>(true);

  const checkApiKeyStatus = useCallback(async () => {
    if (window.aistudio && window.aistudio.hasSelectedApiKey) {
      const hasKey = await window.aistudio.hasSelectedApiKey();
      setApiKeySelected(hasKey);
    } else {
      // Fallback if aistudio API is not available (e.g., local dev)
      console.warn("window.aistudio not found. Assuming API key is set for development.");
      setApiKeySelected(true);
    }
    setLoadingApiKeyCheck(false);
  }, []);

  useEffect(() => {
    checkApiKeyStatus();
  }, [checkApiKeyStatus]);

  const handleApiKeySelected = useCallback(() => {
    setApiKeySelected(true);
  }, []);

  if (loadingApiKeyCheck) {
    return (
      <div className="flex flex-col min-h-screen items-center justify-center bg-gradient-to-br from-indigo-950 to-purple-950 text-purple-200">
        <div className="animate-spin rounded-full h-16 w-16 border-t-2 border-b-2 border-purple-400"></div>
        <p className="mt-4 text-lg">Initializing MansionOS...</p>
      </div>
    );
  }

  if (!apiKeySelected) {
    return <ApiKeyGuard onApiKeySelected={handleApiKeySelected} />;
  }

  return (
    <div className="flex flex-col min-h-screen bg-gradient-to-br from-indigo-950 to-purple-950 text-purple-200">
      <MansionOSHeader />
      <div className="flex-grow container mx-auto px-4 py-8 sm:px-6 lg:px-8">
        <Tabs activeTab={activeWing} onTabChange={setActiveWing}>
          <Tab tabId={ActiveWing.Chat}>Chat Wing</Tab>
          <Tab tabId={ActiveWing.Image}>Image Forge</Tab>
          <Tab tabId={ActiveWing.Voice}>Voice Library</Tab>
        </Tabs>

        <div className="mt-6 p-6 bg-purple-900 bg-opacity-30 backdrop-blur-sm rounded-lg shadow-xl border border-purple-700">
          <TabPanel tabId={ActiveWing.Chat} activeTab={activeWing}>
            <ChatWing />
          </TabPanel>
          <TabPanel tabId={ActiveWing.Image} activeTab={activeWing}>
            <ImageForge />
          </TabPanel>
          <TabPanel tabId={ActiveWing.Voice} activeTab={activeWing}>
            <VoiceLibrary />
          </TabPanel>
        </div>
      </div>
    </div>
  );
}

export default App;

import React from 'react';

interface TabsProps<T extends string> {
  // Fix: Changed children type to React.ReactNode for broader compatibility.
  children: React.ReactNode;
  activeTab: T;
  onTabChange: (tabId: T) => void;
  className?: string;
}

export function Tabs<T extends string>({ children, activeTab, onTabChange, className }: TabsProps<T>): React.ReactNode {
  return (
    <div className={`flex space-x-2 p-1 rounded-lg bg-purple-900 bg-opacity-40 backdrop-blur-sm shadow-md ${className || ''}`}>
      {React.Children.map(children, (child) =>
        React.cloneElement(child, {
          isActive: (child as React.ReactElement<TabProps<T>>).props.tabId === activeTab,
          onClick: () => onTabChange((child as React.ReactElement<TabProps<T>>).props.tabId),
        }),
      )}
    </div>
  );
}

interface TabProps<T extends string> extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  tabId: T;
  children: React.ReactNode;
  isActive?: boolean;
  onClick?: () => void;
  // Fix: Explicitly add className to TabProps, as it was not correctly inferred
  // from React.ButtonHTMLAttributes in the current setup.
  className?: string;
}

export function Tab<T extends string>({ tabId, children, isActive = false, onClick, className, ...props }: TabProps<T>): React.ReactNode {
  const activeClasses = 'bg-purple-600 text-white shadow-lg';
  const inactiveClasses = 'text-purple-200 hover:bg-purple-800 hover:text-white';

  return (
    <button
      type="button"
      className={`
        px-4 py-2 rounded-md text-sm font-medium transition-colors duration-200
        ${isActive ? activeClasses : inactiveClasses}
        ${className || ''}
      `}
      onClick={onClick}
      aria-controls={`tabpanel-${tabId}`}
      aria-selected={isActive}
      id={`tab-${tabId}`}
      role="tab"
      {...props}
    >
      {children}
    </button>
  );
}

interface TabPanelProps<T extends string> {
  tabId: T;
  activeTab: T;
  children: React.ReactNode;
  className?: string;
}

export function TabPanel<T extends string>({ tabId, activeTab, children, className }: TabPanelProps<T>): React.ReactNode {
  return (
    <div
      role="tabpanel"
      id={`tabpanel-${tabId}`}
      aria-labelledby={`tab-${tabId}`}
      hidden={tabId !== activeTab}
      className={tabId === activeTab ? `block ${className || ''}` : 'hidden'}
    >
      {children}
    </div>
  );
}

