import React, { useState, useCallback, useRef, useEffect } from 'react';
import { Button } from './common/Button';
import { Loader } from './common/Loader';
import { GlyphMeta } from '../types';

export const ChronicleMirror: React.FC = () => {
  const [contextInput, setContextInput] = useState<string>('');
  const [intensityInput, setIntensityInput] = useState<number>(50);
  const [glyphs, setGlyphs] = useState<GlyphMeta[]>([]);
  const [searchTerm, setSearchTerm] = useState<string>('');
  const [loading, setLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);

  const glyphsEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = useCallback(() => {
    glyphsEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, []);

  useEffect(() => {
    scrollToBottom();
  }, [glyphs]);

  // Simulate unique ID generation
  const generateId = useCallback(() => `glyph-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`, []);

  const handleRegisterGlyph = useCallback(async (e: React.FormEvent) => {
    e.preventDefault();
    if (!contextInput.trim() || loading) return;

    setError(null);
    setLoading(true);

    try {
      // Simulate asynchronous registration
      await new Promise(resolve => setTimeout(resolve, 500)); 

      const newGlyph: GlyphMeta = {
        id: generateId(),
        context: contextInput,
        timestamp: new Date().toISOString(),
        intensity: intensityInput,
      };

      setGlyphs(prev => [newGlyph, ...prev]); // Add new glyph to the top
      setContextInput('');
      setIntensityInput(50); // Reset intensity
    } catch (err: any) {
      console.error("Glyph registration error:", err);
      setError(err.message || "Failed to engrave glyph. Temporal distortion detected.");
    } finally {
      setLoading(false);
    }
  }, [contextInput, intensityInput, loading, generateId]);

  const filteredGlyphs = glyphs.filter(glyph =>
    glyph.context.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="flex flex-col h-[calc(100vh-250px)] md:h-[calc(100vh-200px)]">
      <h3 className="text-xl font-bold mb-4 text-purple-300">Chronicle Mirror - Constellus Witness</h3>

      <form onSubmit={handleRegisterGlyph} className="mb-6 sticky top-0 bg-purple-900 bg-opacity-30 p-4 -mx-4 -my-4 rounded-t-lg">
        <textarea
          value={contextInput}
          onChange={(e) => setContextInput(e.target.value)}
          placeholder="Describe the moment to engrave (context)..."
          rows={3}
          className="w-full p-3 rounded-lg bg-purple-800 bg-opacity-60 text-white placeholder-purple-300 border border-purple-700 focus:outline-none focus:ring-2 focus:ring-purple-500 mb-4"
          disabled={loading}
          aria-label="Glyph context"
        ></textarea>
        <div className="flex flex-col sm:flex-row items-center justify-between space-y-4 sm:space-y-0 sm:space-x-4 mb-4">
          <div className="flex items-center space-x-2 w-full sm:w-auto">
            <label htmlFor="intensity" className="text-purple-200 font-medium whitespace-nowrap">Intensity (0-100):</label>
            <input
              type="range"
              id="intensity"
              min="0"
              max="100"
              value={intensityInput}
              onChange={(e) => setIntensityInput(Number(e.target.value))}
              className="flex-grow accent-purple-500 w-full"
              disabled={loading}
              aria-label="Glyph intensity"
            />
            <span className="text-purple-200 font-bold w-12 text-right">{intensityInput}</span>
          </div>
          <Button type="submit" loading={loading} disabled={loading} className="w-full sm:w-auto">
            {loading ? 'Engraving Glyph...' : 'Register Glyph'}
          </Button>
        </div>
        <input
            type="text"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            placeholder="Search glyphs by context..."
            className="w-full p-3 rounded-lg bg-purple-800 bg-opacity-60 text-white placeholder-purple-300 border border-purple-700 focus:outline-none focus:ring-2 focus:ring-purple-500"
            disabled={loading}
            aria-label="Search glyphs"
          />
      </form>

      {error && (
        <div className="bg-red-800 bg-opacity-50 text-red-200 p-3 rounded-md mb-4 text-sm" role="alert">
          Error: {error}
        </div>
      )}

      <div className="flex-grow overflow-y-auto pr-2 custom-scrollbar grid grid-cols-1 gap-4">
        {filteredGlyphs.length === 0 && !loading && !searchTerm && (
          <p className="text-center text-gray-400 col-span-full">No glyphs registered yet. Engrave a moment!</p>
        )}
        {filteredGlyphs.length === 0 && !loading && searchTerm && (
          <p className="text-center text-gray-400 col-span-full">No glyphs found matching "{searchTerm}".</p>
        )}
        {loading && (
          <div className="col-span-full flex flex-col items-center justify-center p-8 bg-purple-800 bg-opacity-40 rounded-lg">
            <Loader size="lg" />
            <p className="mt-4 text-lg text-purple-200">Constellus is witnessing... Standby for inscription.</p>
          </div>
        )}
        {filteredGlyphs.map((glyph) => (
          <div key={glyph.id} className="bg-indigo-800 bg-opacity-40 p-4 rounded-lg shadow-md border border-indigo-700">
            <p className="text-xs text-gray-400 mb-1">{new Date(glyph.timestamp).toLocaleString()}</p>
            <p className="text-base text-gray-100 font-medium whitespace-pre-wrap mb-2">{glyph.context}</p>
            <div className="flex items-center justify-between text-sm">
              <span className="text-purple-300">ID: {glyph.id.substring(0, 10)}...</span>
              <span className="text-purple-300">Intensity: <span className="font-bold">{glyph.intensity}</span></span>
            </div>
          </div>
        ))}
        <div ref={glyphsEndRef} />
      </div>
    </div>
  );
};

